import{_ as o,C as t,o as i,c as s,E as a,a2 as l}from"./chunks/framework.Bx6eOp9J.js";const f=JSON.parse('{"title":"记忆恢复了，待处理工作也恢复了吗？","description":"","frontmatter":{"title":"记忆恢复了，待处理工作也恢复了吗？","date":"2026-11-03","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"检查点保留已观察记忆时，是否也保留尚未观察的收件箱？","summary":"固定源码的隔离类探针显示，历史记忆与待处理收件箱可能跨越不同持久化边界；辅助函数存在不等于检查点已经调用它。","sources":["https://github.com/FoundationAgents/MetaGPT/blob/main/metagpt/roles/role.py","https://github.com/FoundationAgents/MetaGPT/blob/main/metagpt/schema.py","https://learn.microsoft.com/en-us/agent-framework/workflows/checkpoints"],"pageClass":"runtime-v6-article","item_id":"SIG-20261103-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-03-sig-20261103-002-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-03-sig-20261103-002.md","filePath":"zh/engineering/2026-11-03-sig-20261103-002.md","lastUpdated":1793707941000}'),h={name:"zh/engineering/2026-11-03-sig-20261103-002.md"};function d(c,e,p,g,m,u){const r=t("ArticleCover"),n=t("ArticleTableScroll");return i(),s("div",null,[a(r,{image:"/assets/covers/daily-2026-11-03-sig-20261103-002-cover.png",kicker:"研究成果",title:"记忆恢复了，待处理工作也恢复了吗？",summary:"固定源码的隔离类探针显示，历史记忆与待处理收件箱可能跨越不同持久化边界；辅助函数存在不等于检查点已经调用它。",version:"2026-11-03",languageHref:"/en/engineering/2026-11-03-sig-20261103-002",languageLabel:"English"}),a(n,{language:"zh"}),e[0]||(e[0]=l('<h1 id="记忆恢复了-待处理工作也恢复了吗" tabindex="-1">记忆恢复了，待处理工作也恢复了吗？ <a class="header-anchor" href="#记忆恢复了-待处理工作也恢复了吗" aria-label="Permalink to &quot;记忆恢复了，待处理工作也恢复了吗？&quot;">​</a></h1><p>对象重新加载成功，历史记录也还在，并不能回答另一件事：崩溃前已经投递、尚未被角色观察的消息去了哪里？本次内部隔离探针在保留已观察记忆的同时，恢复出了空收件箱。这个结果的工程价值，是把“过去知道什么”与“接下来还欠什么工作”分开验收，而不是据此宣布整个框架的崩溃恢复缺陷已经复现。</p><h2 id="已读历史与未读收件箱之间的边界" tabindex="-1">已读历史与未读收件箱之间的边界 <a class="header-anchor" href="#已读历史与未读收件箱之间的边界" aria-label="Permalink to &quot;已读历史与未读收件箱之间的边界&quot;">​</a></h2><p>MetaGPT（多智能体软件协作框架）的角色上下文把待处理消息缓冲区声明为排除序列化的字段，并给它一个创建新队列的默认工厂。这里的序列化是把对象写成可保存的数据；排除字段意味着该字段不会由这个模型的常规导出保留。<a href="https://github.com/FoundationAgents/MetaGPT/blob/main/metagpt/roles/role.py" target="_blank" rel="noreferrer">角色源码</a>是项目公开的一手实现事实，不是独立恢复测试。</p><p>在被分析的普通团队保存与恢复路径中，没有看到显式调用收件箱的导出与载入辅助函数。<a href="https://github.com/FoundationAgents/MetaGPT/blob/main/metagpt/team.py" target="_blank" rel="noreferrer">团队源码</a>中的这一观察，只约束已读路径，不能排除外部存储、自定义子类或其他集成。</p><p>“环境历史中还留着消息”也不等于“接收者重新获得了待处理消息”。除非存在经验证的重放过程，否则持久化了某处副本与恢复可继续执行的工作，是不同的命题。</p><h2 id="一个受限探针怎样把两种状态分开" tabindex="-1">一个受限探针怎样把两种状态分开 <a class="header-anchor" href="#一个受限探针怎样把两种状态分开" aria-label="Permalink to &quot;一个受限探针怎样把两种状态分开&quot;">​</a></h2><p>2026-11-03 的分析阶段从已固定的源码中提取角色上下文、消息队列及角色反应模式类，保留其抽象语法树中的类代码不变。探针使用 Pydantic（数据模型验证库）2.12.3，将消息、记忆、动作、基础环境和日志依赖替换为显式的最小替身。它是源码派生的隔离类探针，不是完整框架运行。</p><p>每组先放入一条已经观察过的记忆，再分别投递零、一、三条待处理消息。实验比较模型导出后重新验证的往返路径，以及显式队列导出再载入的对照路径。</p><table tabindex="0"><thead><tr><th style="text-align:right;">输入待处理数</th><th>模型往返恢复的待处理标识</th><th>已观察记忆</th><th>显式辅助函数恢复的待处理标识</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>空</td><td>保留</td><td>空</td></tr><tr><td style="text-align:right;">1</td><td>空</td><td>保留</td><td>原一条标识</td></tr><tr><td style="text-align:right;">3</td><td>空</td><td>保留</td><td>原三条标识，顺序一致</td></tr></tbody></table><p>来源：本次内部隔离类实验，见文末数据。两个非空输入对照显示，测试并非只验证了一个本来就空的队列。已观察记忆保留，也说明“整个对象什么都没恢复”不能解释这个差异。</p><p>模型导出的键中没有待处理缓冲区；重新构造时默认工厂创建空队列，与源码声明相符。显式辅助函数保留了消息标识与顺序，支持的是辅助路径在静止队列上的有限可行性。它没有建立并发快照原子性、持久存储或外部效果恰好一次的保证。</p><h2 id="有工具、有承诺-与实际接上是三回事" tabindex="-1">有工具、有承诺，与实际接上是三回事 <a class="header-anchor" href="#有工具、有承诺-与实际接上是三回事" aria-label="Permalink to &quot;有工具、有承诺，与实际接上是三回事&quot;">​</a></h2><p>消息队列源码提供导出与载入：导出读取消息表示，并在清理阶段放回原对象；载入解析数据并构建新队列。<a href="https://github.com/FoundationAgents/MetaGPT/blob/main/metagpt/schema.py" target="_blank" rel="noreferrer">队列与消息源码</a>说明工具存在。但模型字段被排除、工具存在、保存入口实际调用工具，必须分别检查，不能由其中一项代替其余两项。</p><p>作为规范对照，Microsoft Agent Framework（微软智能体框架）检查点文档把待处理消息和请求、响应纳入状态，并要求兼容的拓扑与身份、自定义状态钩子，以及可信的存储与序列化边界。<a href="https://learn.microsoft.com/en-us/agent-framework/workflows/checkpoints" target="_blank" rel="noreferrer">官方文档</a>提供的是另一种职责约定，没有在本次研究中接受相同恢复测试。</p><p>因此不能据此给两个框架排优劣：一边是隔离实现观察和有限执行，另一边是文档承诺。后者包含待处理状态，也不能单凭文字确立崩溃一致性、恢复后授权有效或外部效果去重。</p><h2 id="这还不是完整产品的故障复现" tabindex="-1">这还不是完整产品的故障复现 <a class="header-anchor" href="#这还不是完整产品的故障复现" aria-label="Permalink to &quot;这还不是完整产品的故障复现&quot;">​</a></h2><p>本次固定的角色、消息定义与团队源码对象指纹分别以 49b1d178、52badcc2、5a983888 开头，完整值保留在实验数据中。这里固定的是源码对象和校验字节，没有声称固定整个仓库提交。探针依赖版本也不是已核验的上游锁文件环境。</p><p>没有执行完整团队、其扩展运行路径、实际消息与记忆模型、自定义恢复钩子、语言模型或崩溃切点。原始问题报告描述过“投递后、观察前”的消息丢失，但获准阅读的评论仅返回不活跃机器人通知，没有实质维护者确认。<a href="https://github.com/FoundationAgents/MetaGPT/issues/2151" target="_blank" rel="noreferrer">问题报告</a>仍是未核实讨论；本次隔离探针只补充了具体模型边界的内部证据。</p><p>由此得到的检查方向是：把已接受、已观察、已执行和已产生外部效果的消息分别记账。在固定完整依赖、使用实际团队的无语言模型测试中，对投递到观察之间的切点逐一核对标识、顺序与接收者；恢复授权和外部效果去重再单独验证。这是后续验证设计，不是已证实的修复方案。尚待回答的是：完整部署是否通过另一条路径保存并重新投递了这些工作？</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>项目源码是公开一手事实；本研究的受限执行是内部实验依据，不能标成独立验证。官方框架文档是规范承诺，问题讨论是来源报告。公开发布、引用或一次实现成功，都不能自动确立普遍有效性。</p><ul><li>开源项目角色与团队实现，2026-11-03 固定读取字节：<a href="https://github.com/FoundationAgents/MetaGPT/blob/main/metagpt/roles/role.py" target="_blank" rel="noreferrer">角色上下文</a>、<a href="https://github.com/FoundationAgents/MetaGPT/blob/main/metagpt/team.py" target="_blank" rel="noreferrer">保存与恢复入口</a>、<a href="https://github.com/FoundationAgents/MetaGPT/blob/main/metagpt/schema.py" target="_blank" rel="noreferrer">消息队列</a>。源码对象指纹和内容校验值见实验数据。</li><li>微软官方检查点文档，读取日期 2026-11-03：<a href="https://learn.microsoft.com/en-us/agent-framework/workflows/checkpoints" target="_blank" rel="noreferrer">状态范围、自定义状态与恢复要求</a>。仅作规范比较。</li><li>项目问题讨论：<a href="https://github.com/FoundationAgents/MetaGPT/issues/2151" target="_blank" rel="noreferrer">消息恢复报告</a>。没有将未核实报告升级为维护者确认。</li><li>本研究中心，2026-11-03：<a href="/joinwell52/assets/evidence/2026-11-03-sig-20261103-002/experiment-data.json">隔离类实验数据</a>、<a href="/joinwell52/assets/evidence/2026-11-03-sig-20261103-002/helper-data.json">队列辅助路径数据</a>、<a href="/joinwell52/assets/evidence/2026-11-03-sig-20261103-002/probe-source.json">原探针源码</a>。源码包装记录同日来源及哈希；本篇没有重新执行或扩展研究。</li></ul>',23))])}const _=o(h,[["render",d]]);export{f as __pageData,_ as default};
